/**
 * Calculates skill match percentage between user's learned skills and job's required skills.
 */
export const calculateMatch = (userSkills = [], requiredSkills = []) => {
  if (!requiredSkills || requiredSkills.length === 0) {
    return { percentage: 100, matchedSkills: [], missingSkills: [], isEligible: true };
  }

  const normalizedUserSkills = userSkills.map(s => s.toLowerCase().trim());
  const matchedSkills = [];
  const missingSkills = [];

  requiredSkills.forEach(req => {
    const isMatch = normalizedUserSkills.some(userSkill => 
      userSkill === req.toLowerCase().trim() ||
      userSkill.includes(req.toLowerCase().trim()) ||
      req.toLowerCase().trim().includes(userSkill)
    );

    if (isMatch) {
      matchedSkills.push(req);
    } else {
      missingSkills.push(req);
    }
  });

  const percentage = Math.round((matchedSkills.length / requiredSkills.length) * 100);

  return {
    percentage,
    matchedSkills,
    missingSkills,
    isEligible: percentage >= 70
  };
};
